 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    boxes = []
    # A frame is a monochrome 4-connected component whose bounding box has
    # all four sides present. Its interior may contain the same color (pattern).
    for color in range(1, 10):
        seen = set()
        for r in range(h):
            for c in range(w):
                if g[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == color and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
                c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
                if r1-r0 < 2 or c1-c0 < 2:
                    continue
                if not (all(g[r0][x] == color for x in range(c0,c1+1)) and
                        all(g[r1][x] == color for x in range(c0,c1+1)) and
                        all(g[y][c0] == color for y in range(r0,r1+1)) and
                        all(g[y][c1] == color for y in range(r0,r1+1))):
                    continue
                pattern = [[g[y][x] == color for x in range(c0+1,c1)] for y in range(r0+1,r1)]
                boxes.append((r0,r1,c0,c1,color,pattern,any(map(any,pattern))))
    # Copy the filled frame's interior pattern into every empty frame of the
    # same dimensions, recoloring the pattern to the recipient's border color.
    for sr0,sr1,sc0,sc1,scolor,pattern,filled in boxes:
        if not filled:
            continue
        for r0,r1,c0,c1,color,other,other_filled in boxes:
            if (r0,r1,c0,c1) == (sr0,sr1,sc0,sc1):
                continue
            if other_filled or (r1-r0, c1-c0) != (sr1-sr0, sc1-sc0):
                continue
            for dy,row in enumerate(pattern, 1):
                for dx,on in enumerate(row, 1):
                    if on:
                        g[r0+dy][c0+dx] = color
    return g
